import sys

def main():
    import sys
    input = sys.stdin.read().split()
    s = input[0]
    t = input[1]

    n, m = len(s), len(t)
    dp = [-1] * (m + 1)
    dp[0] = -2

    for i in range(n):
        for j in range(m, 0, -1):
            if s[i] == t[j - 1]:
                dp[j] = max(dp[j], dp[j - 1] + 1)

    last_used = [-1] * n
    for j in range(1, m + 1):
        last_used[dp[j]] = j - 1

    current = 0
    for i in range(n):
        if last_used[i] != -1:
            current = last_used[i] + 1

    result = "Yes" if current == m else "No"
    print(result)

if __name__ == "__main__":
    main()
